     1        + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a8T*Rrup + HWFactor  + fmag
                                                                                                                      
                                                                                                                                    
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end


