      elseif ( fType .lt. 0.0 ) then                                                                                                
        Frv = 0.0                                                                                                                   
        Fn = 1.0                                                                                                                    
      else                                                                                                                          
        Frv = 0.0                                                                                                                   
        Fn = 0.0                                                                                                                    
      endif                                                                                                                         
	                                                                                                                                   
C     Compute the Hanging Wall term if needed.                                                                                      
      a10h =   3
      if (HWFlag .eq. 1) then                                                                                                       
         call S02_SWUS_HWModel (M, Rrup, Rjb, Rx, Dip, Width, a10h, ztor, specT, HWfactor)                                          
      else                                                                                                                          
         HWFactor = 0.0                                                                                                             
      endif                                                                                                                         
C     Compute the magnitude term.                                                                      
      if (M .lt. Mc1T) then                                                                                                         
         fmag = a2T*(Mc1T-Mc2T) + a3T*(M-Mc1T)                                      
      elseif (M .ge. Mc2T) then                                                                                                     
         fmag = a4T*(M-Mc2T)                                      
      else                                                                                                                          
         fmag = a2T*(M-Mc2T)                                        
      endif                                                                                                                         
	  
C     Compute the ground motion for the given spectral period.                                                                      
         lnY = a1T + a9T*Ztor + a10T*Frv + a11T*Fn                                                       
     1        + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a8T*Rrup + HWFactor  + fmag
                                                                                                                      
                                                                                                                                    
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end


