      Subroutine S04_CruCF_NPP4_013 ( m, Rrup, Rjb, ztor, ftype, dip, Width, Rx, HWFlag,        
     1                                   specT, lnY, sigma, iflag )                                                                 
                                                                                                                                    
      implicit none                                                                                                                 
                                                                                                                                    
      integer MAXPER                                                                                                                
      parameter (MAXPER= 18)
      REAL Period(MAXPER), a1(MAXPER), a2(MAXPER), a3(MAXPER), a10(MAXPER),  a11(MAXPER)                                            
