      REAL a7T, a8T, a9T, Mc1T, Mc2T, a10T, a11T, Fn, Frv, fType, fmag                                                                    
      integer iflag, count1, count2, nPer, i, HWFlag                                                                                
                                                                                                                                    
      data period /   0.0000,   0.0100,   0.0200,   0.0300,   0.0500,   0.0750,   0.1000,   0.1500, 
     1                0.2000,   0.2500,   0.3000,   0.4000,   0.5000,   0.7500,   1.0000,   1.5000, 
     1                2.0000,   3.0000 / 
                                                                                                                                    
      Data a1(1:18) / 1.5279332, 1.5279332, 1.1614851, 1.6865598, 1.4223866, 1.2141382, 2.475413, 2.1468081, 4.076508, 2.5238227,
     1      1.1768682, 2.794576, 2.3313466, 1.6770134, 0.97231864, 0.32889535, 0.34808665, -0.63107502/
      Data a2(1:18) / -0.029325984, -0.029325984, -0.13119322, 0.092837823, -0.04849857, -0.091743159, -0.049960514, -0.054173703,
     1      0.117857, 0.30212498, 0.71980626, 0.49111729, 0.3988358, 0.77478478, 0.17882277, 0.71200321, 0.95954554, 0.82398391/
      Data a3(1:18) / 0.18620812, 0.18620812, 0.2710781, 0.03808789, 0.39375057, -0.23817566, -0.035905877, 0.078065875,
     1      0.45069752, 0.70855852, 0.67761392, 0.81636388, 0.84752262, 0.86381433, 1.0280579, 1.7216432, 1.3709789, 1.7611015/
      Data a4(1:18) / -0.3286359, -0.3286359, -0.20177345, -0.18965682, -0.36231121, -0.20851316, -0.29909362, -0.36192848,
     1      -0.25684131, -0.36983134, -0.21004122, -0.11773895, -0.34206713, -0.22091262, -0.18143005, -0.22150072, -0.30545158,
     1      0.22293685/
      Data a5(1:18) / -1.6561482, -1.6561482, -1.5987829, -1.6457797, -1.5085586, -1.3397305, -1.7136262, -1.490444, -2.1521883,
     1      -1.6558414, -1.1248399, -1.6270367, -1.5824621, -1.4717591, -1.4406564, -1.3307587, -1.4454049, -1.3613475/
      Data a6(1:18) / 0.25912628, 0.25912628, 0.27078357, 0.25219771, 0.26057546, 0.23980848, 0.25462941, 0.26224866, 0.26253722,
     1      0.22903932, 0.17642447, 0.18204995, 0.23659814, 0.20054011, 0.21660064, 0.21373506, 0.24442509, 0.20498249/
      Data a9(1:18) / 0.013638813, 0.013638813, 0.012925433, 0.014086636, 0.0092431078, 0.034002704, 0.01588556, 0.017300455,
     1      0.012225714, 0.021194155, 0.020052081, 0.013529583, 0.011445193, 0.0079434092, 0.010115135, 0.0093721954, 0.012894874,
     1      0.0090515489/
      Data a10(1:18) / 0.22592606, 0.22592606, 0.18576066, 0.15168493, 0.25964415, -0.019663815, 0.1404987, 0.1156492, 0.2029716,
     1      0.20754764, 0.080587247, 0.25227951, 0.19632276, 0.16796722, 0.23174033, 0.13583971, 0.07954589, 0.0066595354/
      Data a11(1:18) / 0.012869284, 0.012869284, -0.033920599, 0.00095415062, 0.030189667, -0.020448255, 0.082268372, -0.042915201,
     1      0.033980137, 0.025444934, 0.035305476, -0.13535888, -0.14831489, -0.14502689, -0.10099985, -0.046083192, -0.24120119,
     1      -0.12727274/
      Data a7(1:18) / 7.7630332, 7.7630332, 4.3014807, 7.3387857, 5.2510196, 7.5079446, 8.0235809, 8.8104059, 11.404568, 7.0054624,
     1      4.3084805, 9.4009176, 10.171332, 8.8796454, 7.1790921, 7.9091974, 5.8268003, 5.9623377/
      Data a8(1:18) / -0.0038205213, -0.0038205213, -0.004835984, -0.003608002, -0.0046842228, -0.010852787, -0.0051922661,
     1      -0.0090011151, -0.0017013531, -0.0024206109, -0.0052283182, -0.00086712622, -0.0028201975, -2.6317033e-06,
     1      -0.00010957012, -0.0016790196, -0.0020983127, -0.0028388095/
      Data Mc1(1:18) / 5.7979553, 5.7979553, 5.7811383, 6.0474842, 5.8156168, 6.2948503, 5.8124831, 5.7294059, 5.9112273,
     1      5.5885545, 5.7677016, 6.2094198, 5.9845872, 5.8590988, 5.8332126, 5.8595099, 6.0863668, 5.867364/
      Data Mc2(1:18) / 7.2862899, 7.2862899, 7.1489868, 6.1719658, 6.5148881, 6.8435099, 6.228502, 6.6121523, 6.6889738, 6.93903,
     1      6.4191686, 6.9388251, 6.8873662, 6.76979, 6.7305085, 6.8099829, 6.9846891, 6.4677397/
                                                                                                                                    
C Find the requested spectral period and corresponding coefficients                                                                 
      nPer =    18
C First check for the PGA case (i.e., specT=0.0)                                                                                    
      if (specT .eq. 0.0) then                                                                                                      
        period1  = period(1)                                                                                                        
        a1T      = a1(1)                                                                                                            
        a2T      = a2(1)                                                                                                            
        a3T      = a3(1)                                                                                                            
        a4T      = a4(1)                                                                                                            
        a5T      = a5(1)                                                                                                            
        a6T      = a6(1)                                                                                                            
        a7T      = a7(1)                                                                                                            
        a8T      = a8(1)                                                                                                            
        a9T      = a9(1)                                                                                                            
        Mc1T      = Mc1(1)                                                                                                          
        Mc2T      = Mc2(1)                                                                                                          
        a10T      = a10(1)                                                                                                          
        a11T      = a11(1)                                                                                                          
        goto 1011                                                                                                                   
      elseif (specT .gt. 0.0) then                                                                                                  
C Now loop over the spectral period range of the attenuation relationship.                                                          
         do i=2,nper-1                                                                                                              
            if (specT .ge. period(i) .and. specT .le. period(i+1) ) then                                                            
               count1 = i                                                                                                           
               count2 = i+1                                                                                                         
               goto 1020                                                                                                            
            endif                                                                                                                   
         enddo                                                                                                                      
      endif                                                                                                                         
                                                                                                                                    
C Selected spectral period is outside range defined by attenuaton model.                                                            
      write (*,*)                                                                                                                   
      write (*,*) 'Crustal Common Model017 Horizontal'
      write (*,*) 'attenuation model is not defined for a '                                                                         
      write (*,*) ' spectral period of: '                                                                                           
      write (*,'(a10,f10.5)') ' Period = ',specT                                                                                    
      write (*,*) 'This spectral period is outside the defined'                                                                     
      write (*,*) 'period range in the code or beyond the range'                                                                    
      write (*,*) 'of spectral periods for interpolation.'                                                                          
      write (*,*) 'Please check the input file.'                                                                                    
      write (*,*)                                                                                                                   
      stop 99                                                                                                                       
                                                                                                                                    
C Interpolate the coefficients for the requested spectral period.                                                                   
 1020 call S24_interp (period(count1),period(count2),a1(count1),a1(count2),                                                         
     +             specT,a1T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a2(count1),a2(count2),                                                         
     +             specT,a2T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a3(count1),a3(count2),                                                         
     +             specT,a3T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a4(count1),a4(count2),                                                         
     +             specT,a4T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a5(count1),a5(count2),                                                         
     +             specT,a5T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a6(count1),a6(count2),                                                         
     +             specT,a6T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a7(count1),a7(count2),                                                         
     +             specT,a7T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a8(count1),a8(count2),                                                         
     +             specT,a8T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a9(count1),a9(count2),                                                         
     +             specT,a9T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),Mc1(count1),Mc1(count2),                                                       
     +             specT,Mc1T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),Mc2(count1),Mc2(count2),                                                       
     +             specT,Mc2T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),a10(count1),a10(count2),                                                       
     +             specT,a10T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),a11(count1),a11(count2),                                                       
     +             specT,a11T,iflag)                                                                                                
                                                                                                                                    
 1011 period1 = specT                                                                                                               
                                                                                                                                    
      if ( fType .gt. 0.0 ) then                                                                                                    
        Frv = 1.0                                                                                                                   
        Fn = 0.0                                                                                                                    
      elseif ( fType .lt. 0.0 ) then                                                                                                
        Frv = 0.0                                                                                                                   
        Fn = 1.0                                                                                                                    
      else                                                                                                                          
        Frv = 0.0                                                                                                                   
        Fn = 0.0                                                                                                                    
      endif                                                                                                                         
	                                                                                                                                   
C     Compute the Hanging Wall term if needed.                                                                                      
      a10h =   3
      if (HWFlag .eq. 1) then                                                                                                       
         call S02_SWUS_HWModel (M, Rrup, Rjb, Rx, Dip, Width, a10h, ztor, specT, HWfactor)                                          
      else                                                                                                                          
         HWFactor = 0.0                                                                                                             
      endif                                                                                                                         
C     Compute the magnitude term.                                                                      
      if (M .lt. Mc1T) then                                                                                                         
         fmag = a2T*(Mc1T-Mc2T) + a3T*(M-Mc1T)                                      
      elseif (M .ge. Mc2T) then                                                                                                     
         fmag = a4T*(M-Mc2T)                                      
      else                                                                                                                          
         fmag = a2T*(M-Mc2T)                                        
      endif                                                                                                                         
	  
C     Compute the ground motion for the given spectral period.                                                                      
         lnY = a1T + a9T*Ztor + a10T*Frv + a11T*Fn                                                       
     1        + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a8T*Rrup + HWFactor  + fmag
                                                                                                                      
                                                                                                                                    
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end


